import React, { useState } from "react";

import Sidebar from "./components/Sidebar";
import Header from "./components/Header";
import MetricCard from "./components/MetricCard";
import TopologyGraph from "./components/TopologyGraph";
import Workers from "./components/Workers";

import { systemMetrics } from "./data/mockData";

import "./App.css";


function App() {

  const [activePage, setActivePage] = useState("overview");


  const renderPage = () => {

    switch (activePage) {

      case "workers":
        return <Workers />;

      case "topology":
        return (
          <div>
            <h1>Topology</h1>
            <p>Detailed StreamForge topology view.</p>
          </div>
        );

      case "partitions":
        return <Partitions />;

      case "metrics":
        return (
          <div>
            <h1>Metrics</h1>
            <p>Detailed processing metrics will appear here.</p>
          </div>
        );

      case "overview":
      default:

        return (
          <>
            <div className="page-title">

              <div>
                <h1>
                  System Overview
                </h1>

                <p>
                  Monitor the StreamForge distributed streaming pipeline
                </p>
              </div>

              <div className="system-status">
                <span className="status-dot"></span>
                All Systems Operational
              </div>

            </div>


            <section className="metrics-grid">

              <MetricCard
                title="Events / Sec"
                value={systemMetrics.eventsPerSecond.toLocaleString()}
                subtitle="Current throughput"
                trend={systemMetrics.throughputTrend}
                trendType="positive"
              />


              <MetricCard
                title="Workers"
                value={`${systemMetrics.activeWorkers} / ${systemMetrics.totalWorkers}`}
                subtitle="Active workers"
                trend={
                  systemMetrics.failedWorkers === 0
                    ? "Healthy"
                    : `${systemMetrics.failedWorkers} Failed`
                }
                trendType={
                  systemMetrics.failedWorkers === 0
                    ? "positive"
                    : "negative"
                }
              />


              <MetricCard
                title="Partitions"
                value={`${systemMetrics.activePartitions} / ${systemMetrics.totalPartitions}`}
                subtitle="Active partitions"
                trend={
                  systemMetrics.activePartitions ===
                  systemMetrics.totalPartitions
                    ? "All active"
                    : "Attention"
                }
                trendType={
                  systemMetrics.activePartitions ===
                  systemMetrics.totalPartitions
                    ? "positive"
                    : "negative"
                }
              />


              <MetricCard
                title="Processing Latency"
                value={`${systemMetrics.processingLatency} ms`}
                subtitle="Average latency"
                trend={systemMetrics.latencyTrend}
                trendType="positive"
              />

            </section>


            <section className="topology-section">

              <div className="section-header">

                <div>

                  <h2>
                    Live Stream Topology
                  </h2>

                  <p>
                    Real-time view of the StreamForge processing pipeline
                  </p>

                </div>


                <div className="live-indicator">

                  <span className="status-dot"></span>

                  LIVE

                </div>

              </div>


              <div className="topology-container">

                <TopologyGraph />

              </div>

            </section>
          </>
        );
    }
  };


  return (

    <div className="app">

      <Sidebar
        activePage={activePage}
        setActivePage={setActivePage}
      />


      <main className="main-content">

        <Header />


        <div className="dashboard-content">

          {renderPage()}

        </div>

      </main>

    </div>

  );
}


export default App;
